-- Heroes of Horror spell definitions.
-- Source: Heroes of Horror, Chapter 5, pp. 125-133. Mechanical text is summarized; source pages remain authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('hoh-3.5','heroes-of-horror-3-5','Heroes of Horror','HoH','Wizards of the Coast','dnd','3.5',
        'D&D 3.5 horror supplement covering dread campaigns, taint, horror character options, magic, and monsters.',NULL,1,0,NULL);

INSERT OR IGNORE INTO dnd35_spells
(id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,school_id,subschool,casting_time,action_type,range_text,target_text,area_text,effect_text,duration_text,saving_throw_text,save,spell_resistance,spell_resistance_text) VALUES
  ('hoh-spell-bestow-wound','hoh-3.5','127','bestow-wound','Bestow Wound','Transfers some of the caster’s wounds to a touched living creature, healing the caster by the same amount.','On a failed Fortitude save, the target takes damage equal to the caster’s current wounds, capped at 1 point per caster level and at the amount required to restore the caster to maximum hit points; the caster heals the same amount.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 action',NULL,'Touch','Living creature touched',NULL,NULL,'Instantaneous','Fortitude negates','fort','yes','Yes'),
  ('hoh-spell-call-forth-the-beast','hoh-3.5','127-128','call-forth-the-beast','Call Forth the Beast','A corrupt spell that causes a sleeping humanoid to awaken chaotic evil and violently bloodthirsty for 1 hour/level.','The effect lies dormant until the subject next sleeps, then the subject awakens chaotic evil and prone to indiscriminate violence. When the effect ends, the subject loses consciousness briefly and remembers none of the episode. Corruption cost: 1d4 Constitution damage.',0,NULL,1,'phb-spell-school-enchantment','Compulsion','1 round',NULL,'Close (25 ft. + 5 ft./2 levels)','One humanoid of Hit Dice equal to caster level +4 or less',NULL,NULL,'Permanent until discharged, then 1 hour/level (D)','Will negates','will','yes','Yes'),
  ('hoh-spell-chain-of-sorrow','hoh-3.5','128','chain-of-sorrow','Chain of Sorrow','A corrupt spell that drains Charisma and can pass from a failed victim to the next friend or ally touched.','The first target takes 2d10 Charisma drain, Will half. A successful save ends the spell; on failure the effect passes to the next friend, loved one, or ally the victim touches, repeating until a save succeeds or the chain has affected caster level creatures. Corruption cost: 2d4 Charisma damage.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One living creature to start, possibly more; see text',NULL,NULL,'See text','Will half, and see text','will','yes','Yes'),
  ('hoh-spell-cloak-of-hate','hoh-3.5','128','cloak-of-hate','Cloak of Hate','Makes a living subject instinctively hated by strangers and acquaintances.','NPC reactions toward the subject begin one category worse and Diplomacy checks to improve those reactions take a -10 circumstance penalty. Others tend to interpret the subject in the worst possible light; close friends and loved ones are unaffected.',0,NULL,1,'phb-spell-school-enchantment',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'1 day/level','Will negates','will','yes','Yes'),
  ('hoh-spell-detect-taint','hoh-3.5','128','detect-taint','Detect Taint','Detects the presence, number, strength, and location of tainted auras over successive rounds.','Round 1 reveals presence of taint; round 2 reveals number and strongest aura, with possible nausea from an overwhelming aura; round 3 reveals strength and location of each aura. Aura strength and lingering duration follow the taint tables in the spell entry.',0,NULL,1,'phb-spell-school-divination',NULL,'1 standard action',NULL,'60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 10 min./level (D)','None',NULL,'no','No'),
  ('hoh-spell-dream-sight','hoh-3.5','128','dream-sight','Dream Sight','Sends the caster’s spirit from the sleeping body as an incorporeal observer moving 100 feet per round.','While the body sleeps, the spirit travels incorporeally at 100 feet per round and can see and hear but cannot speak, attack, cast spells, or take other actions. Disturbing the body ends the spell and returns the spirit immediately.',0,NULL,1,'phb-spell-school-divination',NULL,'1 full round',NULL,'See text','You',NULL,NULL,'1 min/level (D)',NULL,NULL,'no','No'),
  ('hoh-spell-dream-walk','hoh-3.5','129','dream-walk','Dream Walk','Transports a creature or a linked group into the dreamscape of a nearby or visible dreamer.','The caster must be able to see the dreamer whose dreamscape is entered or be within 30 feet of that dreamer. Otherwise the spell functions as plane shift.',0,NULL,1,'phb-spell-school-conjuration','Teleportation','1 standard action',NULL,'Touch','Creature touched, or up to eight willing creatures joining hands',NULL,NULL,'Instantaneous','Will negates','will','yes','Yes'),
  ('hoh-spell-dreaming-puppet','hoh-3.5','129','dreaming-puppet','Dreaming Puppet','Allows the caster to enter a sleeping creature’s dream and control the creature’s physical body.','The caster enters a defenseless trance and, while the named subject sleeps, controls the subject’s body as dominate monster. The subject can gain a new save for commands against its moral code; an exceptionally successful initial save can strand the caster’s soul in the dreamscape.',0,NULL,1,'phb-spell-school-enchantment','Compulsion','1 minute',NULL,'Unlimited','One sentient, living creature of caster’s HD +4 or lower',NULL,NULL,'1 min./level (D)','Will negates','will','yes','Yes'),
  ('hoh-spell-familial-geas','hoh-3.5','129','familial-geas','Familial Geas','Creates an unlimited geas that passes to the subject’s closest adult relative if the subject dies before fulfilling it.','The initial subject receives no save as with geas. If that subject dies before completing the obligation, the geas passes to the closest adult relative, who receives a Will save; this succession continues until the obligation is completed or the effect is broken by the methods specified in the spell.',0,NULL,1,'phb-spell-school-enchantment','Compulsion','10 minutes',NULL,'Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'Until discharged','None or Will negates; see text','will','yes','Yes'),
  ('hoh-spell-fire-in-the-blood','hoh-3.5','129-130','fire-in-the-blood','Fire in the Blood','Makes the caster’s blood corrosive so slashing or piercing melee attackers suffer escalating damage.','Each foe that deals slashing or piercing melee damage is sprayed for cumulative damage: 1d6 on the first qualifying hit, then 2d6, and so on. When any one foe takes 5d6 from a single spray, the spell ends. Bludgeoning and non-slashing/piercing magical attacks do not trigger it.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action',NULL,'Personal','You',NULL,NULL,'1 minute/level','None',NULL,'no','No'),
  ('hoh-spell-harm-greater','hoh-3.5','130','harm-greater','Harm, Greater','Functions as harm at close range but deals 1d12 damage per caster level, maximum 20d12.','As harm except for the listed range and damage: 1d12 points per caster level, maximum 20d12 at caster level 20.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Instantaneous','Will half; see harm','will','yes','Yes'),
  ('hoh-spell-harm-mass','hoh-3.5','130','harm-mass','Harm, Mass','Applies greater harm to every creature except the caster in a 20-foot-radius burst.','Applies greater harm to every creature except the caster in a 20-foot-radius burst.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'20 ft.','All creatures except the caster in the area','20-ft.-radius burst centered on caster',NULL,'Instantaneous','Will half; see greater harm','will','yes','Yes'),
  ('hoh-spell-imprison-soul','hoh-3.5','130','imprison-soul','Imprison Soul','Traps a named creature’s soul in a prepared Tiny or smaller receptacle and leaves the body lifeless.','The receptacle takes three days to prepare and must be within spell range at casting. While trapped, the subject takes 1d4 Constitution damage per day until dead or freed. Destroying or opening the receptacle releases the soul. This entry supersedes earlier published versions.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action; see text',NULL,'Touch','Creature touched',NULL,NULL,'Permanent; see text','Will negates','will','yes','Yes'),
  ('hoh-spell-manifest-desire','hoh-3.5','130','manifest-desire','Manifest Desire','Makes a living target’s greatest desire appear as an illusion visible to everyone.','The illusion reveals the target’s greatest desire. A creature that interacts with the image can attempt a Will save to disbelieve it.',0,NULL,1,'phb-spell-school-illusion',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'Concentration + 3 rounds','Will disbelief (if interacted with)','will','yes','Yes'),
  ('hoh-spell-manifest-nightmare','hoh-3.5','130','manifest-nightmare','Manifest Nightmare','Makes a target’s greatest fear manifest as a visible illusion that can cause panic.','Each round while the nightmare remains nearby, the subject makes a Will save: failure causes panic and success leaves the subject shaken for that round. Interaction can allow a separate disbelief save that ends the fear effect.',0,NULL,1,'phb-spell-school-illusion',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'Concentration + 3 rounds','Will partial or disbelief (if interacted with)','will','yes','Yes'),
  ('hoh-spell-mantle-of-pure-spite','hoh-3.5','130-131','mantle-of-pure-spite','Mantle of Pure Spite','Builds escalating offensive and defensive power against each foe that attacks the caster.','Each time a foe strikes the caster, the caster gains a cumulative +1 on attacks and damage against that foe, up to caster level; attacks against that foe can overcome its damage reduction as though using the required alignment/material; and the caster gains cumulative DR 1/- against that foe, up to DR 15/-. Track each foe separately.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'Personal','You',NULL,NULL,'1 min./level',NULL,NULL,'no','No'),
  ('hoh-spell-masters-lament','hoh-3.5','131','masters-lament','Master’s Lament','A corrupt spell that makes a master and empathically linked companion share damage and magical effects.','For the duration, damage or magical effects suffered by master or familiar/companion are also suffered by the other; if an effect allows a save, they roll separately. The spell can target either member of the link. Corruption cost: 1d6 Charisma damage.',0,NULL,1,'phb-spell-school-transmutation',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One humanoid creature with a familiar or other empathically linked animal companion',NULL,NULL,'1 minute/level','Will negates','will','yes','Yes'),
  ('hoh-spell-oath-of-blood','hoh-3.5','131','oath-of-blood','Oath of Blood','Extends a recent geas beyond death by animating the subject as undead until the task is completed or expires.','Only functions on a creature recently subject to a geas or similar effect. If the subject dies before completing the task, it is animated as an undead creature appropriate to the caster level as with create undead; when the obligation ends, the animation ends and the subject returns to death.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 minute',NULL,'Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'See text','None',NULL,'yes','Yes'),
  ('hoh-spell-pact-of-return','hoh-3.5','131','pact-of-return','Pact of Return','Lets the caster name an expected killer or specific death circumstance and be instantly resurrected if that prediction comes true.','At casting, name a specific creature or reasonably specific circumstance expected to cause the caster’s death. If the caster dies during the duration under sufficiently matching circumstances, resurrection occurs instantly with no level loss. Multiple pacts with distinct triggers can coexist and can be dispelled.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'Personal','You',NULL,NULL,'1 hour/level',NULL,NULL,'no','No'),
  ('hoh-spell-plague-of-undead','hoh-3.5','131-132','plague-of-undead','Plague of Undead','Raises a large group of skeletons or zombies with maximum hit points and places them under the caster’s control.','Creates skeletons or zombies totaling no more than four times caster level in Hit Dice, with maximum hit points for their Hit Dice. Control is indefinite but shares the normal 4 HD per caster level control limit with animate dead; excess previously controlled undead are released as chosen.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One or more corpses within range',NULL,NULL,'Instantaneous','None',NULL,'no','No'),
  ('hoh-spell-pronouncement-of-fate','hoh-3.5','132','pronouncement-of-fate','Pronouncement of Fate','Names a target’s offense and curses the offender with broad penalties, with stronger effects when the offense harmed the caster personally.','Normally imposes -4 on attacks, damage, saves, and checks. If the named offense affected the caster personally, the target also has a 50% chance each turn to lose all actions; its save only halves penalties to -2 and action loss to 25%, and the caster gains +4 to overcome spell resistance. Otherwise a successful Will save negates.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'1 round/level','Will negates or Will partial; see text','will','conditional','Special'),
  ('hoh-spell-resist-taint','hoh-3.5','132','resist-taint','Resist Taint','Grants a +4 resistance bonus on saves made to resist acquiring taint.','Grants a +4 resistance bonus on saves made to resist acquiring taint.',0,NULL,1,'phb-spell-school-abjuration',NULL,'1 standard action',NULL,'Touch','Creature touched',NULL,NULL,'10 min./level','Fortitude negates (harmless)','fort','yes','Yes'),
  ('hoh-spell-restful-slumber','hoh-3.5','132','restful-slumber','Restful Slumber','Allows a living creature to sleep without nightmares and can suppress externally imposed nightmares.','The subject gains uninterrupted sleep without nightmares. Against nightmares imposed by another source, make a caster level check against DC 11 + that source’s caster level.',0,NULL,1,'phb-spell-school-enchantment',NULL,'1 round',NULL,'Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'1 hour/level (D)','Will negates (harmless)','will','yes','Yes'),
  ('hoh-spell-rigor-mortis','hoh-3.5','132','rigor-mortis','Rigor Mortis','Suspends a creature’s apparent vital functions so the subject falls and seems dead.','A failed save causes the subject to fall as if dead; breathing, circulation, and other signs of life are suspended. The target must have a Wisdom score. Physical harm grants another saving throw to awaken. Note: the class list on p.125 lists cleric 3rd, while this spell entry on p.132 states cleric 2nd; this seed uses the detailed spell entry.',0,NULL,1,'phb-spell-school-necromancy',NULL,'1 standard action',NULL,'Touch','Creature touched',NULL,NULL,'1d6+2 rounds','Fortitude negates','fort','yes','Yes'),
  ('hoh-spell-summon-undead-i','hoh-3.5','132','summon-undead-i','Summon Undead I','Summons one undead creature from the 1st-level Summon Undead list.','Functions as summon monster I except it summons undead. Choices: human warrior skeleton or kobold zombie. Summoned undead do not count against controlled-undead Hit Dice; no summoned undead can exceed caster level +1 Hit Dice. This entry supersedes earlier published versions.',0,NULL,1,'phb-spell-school-conjuration','Summoning','1 round',NULL,'Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One summoned creature','1 round/level','None',NULL,'no','No'),
  ('hoh-spell-summon-undead-ii','hoh-3.5','132','summon-undead-ii','Summon Undead II','Summons one 2nd-level-list undead or two identical creatures from the 1st-level list.','Functions as summon undead I. The 2nd-level list contains owlbear skeleton and bugbear zombie.',0,NULL,1,'phb-spell-school-conjuration','Summoning','1 round',NULL,'Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more summoned creatures, no two more than 30 ft. apart','1 round/level','None',NULL,'no','No'),
  ('hoh-spell-summon-undead-iii','hoh-3.5','132-133','summon-undead-iii','Summon Undead III','Summons one 3rd-level-list undead, two identical 2nd-level-list undead, or four identical 1st-level-list undead.','Functions as summon undead I. The 3rd-level list contains ghoul, troll skeleton, and ogre zombie.',0,NULL,1,'phb-spell-school-conjuration','Summoning','1 round',NULL,'Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more summoned creatures, no two more than 30 ft. apart','1 round/level','None',NULL,'no','No'),
  ('hoh-spell-summon-undead-iv','hoh-3.5','133','summon-undead-iv','Summon Undead IV','Summons one 4th-level-list undead, two identical 3rd-level-list undead, or four identical creatures from a lower list.','Functions as summon undead I. The 4th-level list contains allip, ghast, and wyvern zombie.',0,NULL,1,'phb-spell-school-conjuration','Summoning','1 round',NULL,'Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more summoned creatures, no two more than 30 ft. apart','1 round/level','None',NULL,'no','No'),
  ('hoh-spell-summon-undead-v','hoh-3.5','133','summon-undead-v','Summon Undead V','Summons one 5th-level-list undead, two identical 4th-level-list undead, or four identical creatures from a lower list.','Functions as summon undead I. The 5th-level list contains mummy, shadow, vampire spawn, and wight.',0,NULL,1,'phb-spell-school-conjuration','Summoning','1 round',NULL,'Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'One or more summoned creatures, no two more than 30 ft. apart','1 round/level','None',NULL,'no','No'),
  ('hoh-spell-vile-death','hoh-3.5','133','vile-death','Vile Death','Binds a fiendish spirit into a corporeal undead creature, applying the fiendish template.','The target undead gains the fiendish template. The resulting creature is independent and initially indifferent to the caster. Material component includes a bloodstone worth at least 500 gp; XP cost 100.',0,NULL,1,'phb-spell-school-conjuration','Calling','1 hour',NULL,'Touch','One corporeal undead creature',NULL,NULL,'Permanent (D)','None',NULL,'yes','Yes');
